import xml.etree.ElementTree as ET


class SCFFactory(object):
    """
    Factory that creates SCFModel objects from provided scf.xml file

    FDEV: TO BE MOVED TO: taf.internal.datamodel.nidd

    """
    def __init__(self, scf_xml_path):
        self.cm_data, self.namespace = self.__load_scf(scf_xml_path)

    def get_scf_model(self):
        """

        :return SCFModel:
        :raises InvalidSCFHeader: InvalidSCFHeader if SCF header does not contain creation log.
        """
        managed_xml_elements = self.__get_managed_objects_xmls()
        scf_managed_objects = self.__create_managed_objects(element_list=managed_xml_elements)
        app_version = self.__get_app_version()
        return SCFModel(scf_managed_objects=scf_managed_objects, app_version=app_version)

    def __load_scf(self, scf_xml_path):
        scf_xml = ET.parse(scf_xml_path)
        scf_root = scf_xml.getroot()
        namespace = self.__get_element_namespace(scf_root)
        cm_data = scf_root.find(self.__add_namespace(namespace, 'cmData'))
        return cm_data, namespace

    def __get_managed_objects_xmls(self):
        return self.cm_data.findall(self.__add_namespace(self.namespace, 'managedObject'))

    def __get_app_version(self):
        header = self.cm_data.find(self.__add_namespace(self.namespace, 'header'))
        header_creation_log = header.find(self.__add_namespace(self.namespace, 'log'))
        if header_creation_log is None:
            raise InvalidSCFHeader(
                "SCF Header does not contain information about sw application for which it has been generated")
        app_version = header_creation_log.get("appVersion")
        return app_version

    def __create_managed_objects(self, element_list):
        return [SCFManagedObject.from_xml(element) for element in element_list]

    def __get_element_namespace(self, element):
        return element.tag.rsplit('}')[0][1:]

    def __add_namespace(self, namespace, name):
        return '{{{}}}{}'.format(namespace, name)


class SCFModel(object):
    def __init__(self, scf_managed_objects, app_version):
        """

        :param scf_managed_objects:
        :param app_version:
        """
        self.managed_objects = scf_managed_objects
        self.app_version = app_version


class SCFManagedObject(object):
    def __init__(self, dist_name, version, parameters):
        """

        :param dist_name:
        :param version:
        :param parameters:
        """
        self.dist_name = dist_name
        self.moc_name = self.__dist_name_to_moc_name(dist_name)
        self.parameters = parameters
        self.version = version

    @classmethod
    def from_xml(cls, xml_element):
        dist_name = xml_element.attrib['distName']
        version = xml_element.attrib['version']
        parameters = cls.__parse_mobj_xml_children(xml_element)
        return cls(dist_name=dist_name, version=version, parameters=parameters)

    @classmethod
    def __dist_name_to_moc_name(cls, dist_name):
        segments = dist_name.split('/')
        segments = [segment.split('-')[0] for segment in segments]
        return '/'.join(segments)

    @classmethod
    def __parse_mobj_xml_children(cls, managed_object_xml):
        return [cls.__parse_parameter_xml(child) for child in managed_object_xml]

    @classmethod
    def __parse_parameter_xml(cls, parameter_xml):
        """
        Elements with no subelements will test as False.
        Elements with no subelements will len(element) equal 0.
        """
        if len(parameter_xml):
            return SCFParameterList.from_xml(xml_element=parameter_xml)
        else:
            return SCFParameter.from_xml(xml_element=parameter_xml)


class SCFParameter(object):
    def __init__(self, name, value):
        """

        :param name:
        :param value:
        """
        self.name = name
        self.value = value

    @classmethod
    def from_xml(cls, xml_element):
        """

        :param xml_element:
        :return:
        """
        name = xml_element.attrib['name']
        value = xml_element.text
        return cls(name, value)


class SCFParameterList(object):
    def __init__(self, name, parameters):
        """

        :param name:
        :param parameters:
        """
        self.name = name
        self.parameters = parameters

    def __iter__(self):
        return iter(self.parameters)

    @classmethod
    def from_xml(cls, xml_element):
        """

        :param xml_element:
        :return:
        """
        name = xml_element.attrib['name']
        item = xml_element[0]  # TODO magicnumber because 1st element in list is item containing parameters
        parameters = [SCFParameter.from_xml(ptag) for ptag in item]
        return cls(name, parameters)


class InvalidSCFHeader(Exception):
    pass
